#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long d;
    cin >> n >> d;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_map<long long, int> dp;
    int best = 0;
    for (int i = 0; i < n; i++) {
        auto it = dp.find(a[i] - d);
        int length = (it == dp.end() ? 0 : it->second) + 1;
        dp[a[i]] = length;
        best = max(best, length);
    }
    cout << best << "\n";

    return 0;
}

